function portfolioTabHtml(tab) {
  if (tab === "Pengalaman") return timelineHtml(experience);
  if (tab === "Organisasi") return timelineHtml(organizations);
  if (tab === "Keahlian") {
    return (
      '<div class="skills-grid">' +
      skillGroups
        .map(function (g) {
          return (
            "<section><h2>" + g.title + "</h2>" +
            '<div class="chips">' + g.skills.map(function (s) { return '<span class="chip chip-lg">' + s + "</span>"; }).join("") + "</div>" +
            "</section>"
          );
        })
        .join("") +
      "</div>"
    );
  }
  return null; // "Proyek" memakai markup awal
}

